using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Instructor.Pages.Quizzes;
[Authorize(Roles="Instructor")] public class EditModel:PageModel{private readonly ApplicationDbContext _db;private readonly UserManager<ApplicationUser> _users;private readonly ImageStorageService _images;public EditModel(ApplicationDbContext db,UserManager<ApplicationUser> users,ImageStorageService images){_db=db;_users=users;_images=images;}[BindProperty]public QuizInput Input{get;set;}=new();public int QuizId{get;private set;}public string LessonTitle{get;private set;}="";public string? CurrentImageUrl{get;private set;}public class QuizInput{[Required,StringLength(100)]public string Title{get;set;}="";[StringLength(500)]public string Description{get;set;}="";public QuizType Type{get;set;}public bool IsActive{get;set;}public IFormFile? Image{get;set;}public bool RemoveImage{get;set;}}
public async Task<IActionResult> OnGetAsync(int id){var q=await Owned(id);if(q is null)return NotFound();Set(q);return Page();}public async Task<IActionResult> OnPostAsync(int id){var q=await Owned(id);if(q is null)return NotFound();Set(q);if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(!ModelState.IsValid)return Page();q.Title=Input.Title.Trim();q.Description=Input.Description.Trim();q.Type=Input.Type;q.IsActive=Input.IsActive;q.ImageUrl=await _images.ApplyAsync(q.ImageUrl,Input.Image,Input.RemoveImage,_users.GetUserId(User));await _db.SaveChangesAsync();TempData["StatusMessage"]="Quiz updated.";return RedirectToPage("./Manage",new{id});}private void Set(Quiz q){QuizId=q.Id;LessonTitle=q.Lesson.Title;CurrentImageUrl=q.ImageUrl;Input=new(){Title=q.Title,Description=q.Description,Type=q.Type,IsActive=q.IsActive};}private Task<Quiz?> Owned(int id){var uid=_users.GetUserId(User);return _db.Quizzes.Include(q=>q.Lesson).ThenInclude(l=>l.Course).FirstOrDefaultAsync(q=>q.Id==id&&q.Lesson.Course.InstructorId==uid);}}
